from flask.views import MethodView


def test_unimplemented_method_returns_405(app, client):
    class Index(MethodView):
        methods = ["GET", "POST"]

        def get(self):
            return "GET"

    app.add_url_rule("/", view_func=Index.as_view("index"))

    assert client.get("/").data == b"GET"
    rv = client.post("/")
    assert rv.status_code == 405
    allowed = {m.strip() for m in rv.headers["Allow"].split(",")}
    assert "GET" in allowed
    assert "POST" not in allowed


def test_unimplemented_method_uses_405_error_handler(app, client):
    class Index(MethodView):
        methods = ["GET", "DELETE"]

        def get(self):
            return "GET"

    app.add_url_rule("/", view_func=Index.as_view("index"))

    @app.errorhandler(405)
    def handle_405(e):
        return "custom 405", 405

    rv = client.delete("/")
    assert rv.status_code == 405
    assert rv.data == b"custom 405"

import enum

from flask import json as flask_json


class Color(enum.Enum):
    RED = "red"
    ONE = 1


def test_provider_dumps_enum(app):
    assert app.json.dumps({"color": Color.RED}) == '{"color": "red"}'
    assert app.json.dumps([Color.ONE]) == "[1]"


def test_view_returns_enum(app, client):
    @app.route("/")
    def index():
        return {"color": Color.RED, "n": Color.ONE}

    rv = client.get("/")
    assert rv.json == {"color": "red", "n": 1}


def test_dumps_enum_without_app_context():
    assert flask_json.dumps(Color.RED) == '"red"'
    assert flask_json.dumps({"n": Color.ONE}) == '{"n": 1}'

import flask
from flask.testing import FlaskClient


def _add_view(app):
    @app.route("/")
    def index():
        return {
            "remote_addr": flask.request.remote_addr,
            "user_agent": flask.request.user_agent.string,
            "x_foo": flask.request.headers.get("X-Foo"),
        }


def test_client_environ_base(app):
    _add_view(app)
    client = app.test_client(
        environ_base={"REMOTE_ADDR": "10.0.0.5", "HTTP_X_FOO": "bar"}
    )
    data = client.get("/").json

    assert data["remote_addr"] == "10.0.0.5"
    assert data["x_foo"] == "bar"
    assert data["user_agent"].startswith("Werkzeug/")


def test_request_environ_base_takes_precedence(app):
    _add_view(app)
    client = app.test_client(environ_base={"REMOTE_ADDR": "10.0.0.5"})
    data = client.get("/", environ_base={"REMOTE_ADDR": "10.0.0.6"}).json

    assert data["remote_addr"] == "10.0.0.6"


def test_other_clients_unchanged(app):
    _add_view(app)
    app.test_client(environ_base={"REMOTE_ADDR": "10.0.0.5"})

    assert app.test_client().get("/").json["remote_addr"] == "127.0.0.1"


def test_flask_client_class_accepts_environ_base(app):
    _add_view(app)
    client = FlaskClient(
        app, app.response_class, environ_base={"REMOTE_ADDR": "10.0.0.7"}
    )

    assert client.get("/").json["remote_addr"] == "10.0.0.7"

import pytest
from jinja2 import DictLoader

import flask


@pytest.mark.parametrize(
    ("name", "expect"),
    [
        ("page.html.j2", True),
        ("page.HTML.Jinja", True),
        ("feed.xml.jinja2", True),
        ("icon.svg.j2", True),
        ("page.html", True),
        ("mail.txt.j2", False),
        ("page.j2", False),
        ("page.jinja", False),
        ("page.txt", False),
    ],
)
def test_select_jinja_autoescape(app, name, expect):
    assert app.select_jinja_autoescape(name) is expect


def test_select_jinja_autoescape_none(app):
    assert app.select_jinja_autoescape(None) is True


def test_render_template_with_suffix(app):
    app.jinja_options = {
        "loader": DictLoader(
            {"page.html.j2": "{{ value }}", "mail.txt.j2": "{{ value }}"}
        )
    }

    with app.app_context():
        assert flask.render_template("page.html.j2", value="<b>") == "&lt;b&gt;"
        assert flask.render_template("mail.txt.j2", value="<b>") == "<b>"

import re

import pytest

import flask

MESSAGE = (
    "'copy_current_request_context' can only be used when a request context"
    " is active, such as in a view function."
)


def test_app_context_without_request_raises(app):
    with app.app_context():
        with pytest.raises(RuntimeError, match=re.escape(MESSAGE)):
            flask.copy_current_request_context(lambda: None)


def test_no_context_raises():
    with pytest.raises(RuntimeError, match=re.escape(MESSAGE)):
        flask.copy_current_request_context(lambda: None)


def test_request_context_still_works(app):
    with app.test_request_context("/?name=flask"):

        @flask.copy_current_request_context
        def get_name():
            return flask.request.args["name"]

        assert get_name() == "flask"

import re
from types import MappingProxyType

import pytest


def test_processor_returning_none_is_skipped(app):
    @app.shell_context_processor
    def nothing():
        return None

    @app.shell_context_processor
    def extra():
        return {"answer": 42}

    ctx = app.make_shell_context()
    assert ctx["app"] is app
    assert ctx["answer"] == 42


def test_non_mapping_raises(app):
    @app.shell_context_processor
    def bad():
        return [("answer", 42)]

    message = "The shell context processor 'bad' must return a dict or None, not list."
    with pytest.raises(TypeError, match=re.escape(message)):
        app.make_shell_context()


def test_any_mapping_is_accepted(app):
    @app.shell_context_processor
    def proxy():
        return MappingProxyType({"x": 1})

    assert app.make_shell_context()["x"] == 1
